DROP FUNCTION IF EXISTS public.fn_admin_update_training_session(
  uuid, text, text, numeric, integer, text, text, integer, text, text
);

CREATE FUNCTION public.fn_admin_update_training_session(
  p_session_id    uuid,
  p_session_type  text,
  p_title         text,
  p_distance_km   numeric,
  p_duration_min  integer,
  p_pace_target   text,
  p_intensity     text,
  p_rpe_target    integer,
  p_description   text,
  p_coach_notes   text,
  p_warmup_desc   text DEFAULT NULL,
  p_main_desc     text DEFAULT NULL,
  p_cooldown_desc text DEFAULT NULL
)
RETURNS public.training_sessions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_plan_status text;
  v_session     public.training_sessions%ROWTYPE;
BEGIN
  IF NOT (public.fn_is_coach() OR public.fn_is_admin_or_super()) THEN
    RAISE EXCEPTION 'Solo coaches o administradoras pueden editar sesiones de entrenamiento'
      USING ERRCODE = '42501';
  END IF;

  SELECT p.status INTO v_plan_status
  FROM public.training_sessions ts
  JOIN public.training_weeks tw ON tw.id = ts.week_id
  JOIN public.plans p           ON p.id = tw.plan_id
  WHERE ts.id = p_session_id;

  IF v_plan_status IS NULL THEN
    RAISE EXCEPTION 'Sesión % no encontrada', p_session_id;
  END IF;

  IF v_plan_status = 'active' THEN
    RAISE EXCEPTION 'Plan activo: usa fn_adapt_plan para preservar el historial clínico (Ley de Inmutabilidad)';
  END IF;

  UPDATE public.training_sessions
  SET session_type   = p_session_type,
      title          = p_title,
      distance_km    = p_distance_km,
      duration_min   = p_duration_min,
      pace_target    = p_pace_target,
      intensity      = p_intensity,
      rpe_target     = p_rpe_target,
      description    = p_description,
      coach_notes    = p_coach_notes,
      warmup_desc    = p_warmup_desc,
      main_desc      = p_main_desc,
      cooldown_desc  = p_cooldown_desc,
      updated_at     = now()
  WHERE id = p_session_id
  RETURNING * INTO v_session;

  RETURN v_session;
END;
$function$;

GRANT ALL ON FUNCTION public.fn_admin_update_training_session(
  uuid, text, text, numeric, integer, text, text, integer, text, text, text, text, text
) TO anon;
GRANT ALL ON FUNCTION public.fn_admin_update_training_session(
  uuid, text, text, numeric, integer, text, text, integer, text, text, text, text, text
) TO authenticated;
GRANT ALL ON FUNCTION public.fn_admin_update_training_session(
  uuid, text, text, numeric, integer, text, text, integer, text, text, text, text, text
) TO service_role;

CREATE OR REPLACE FUNCTION public.fn_adapt_plan(
  p_plan_id     uuid,
  p_adaptations jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_old_plan    public.plans%ROWTYPE;
  v_new_plan_id uuid;
  v_current_tag text;
  v_next_tag    text;
  v_week        record;
  v_new_week_id uuid;
  v_session     record;
  v_adapt       jsonb;
BEGIN
  IF NOT (public.fn_is_coach() OR public.fn_is_admin_or_super()) THEN
    RAISE EXCEPTION 'Solo coaches o administradoras pueden adaptar planes'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_old_plan FROM public.plans WHERE id = p_plan_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan % no encontrado', p_plan_id;
  END IF;

  IF v_old_plan.status <> 'active' THEN
    RAISE EXCEPTION 'Solo planes activos pueden adaptarse vía fn_adapt_plan (estado actual: %). Planes no-activos usan fn_admin_update_training_session.', v_old_plan.status;
  END IF;

  v_current_tag := coalesce(v_old_plan.version_tag, 'v1.0');
  v_next_tag := split_part(v_current_tag, '.', 1) || '.' ||
    (coalesce(nullif(split_part(v_current_tag, '.', 2), '')::int, 0) + 1)::text;

  INSERT INTO public.plans (
    runner_id, coach_id, title, goal, current_level, weekly_km_base, days_per_week,
    notes, coach_message, status, generated_at, parent_plan_id, version_tag
  ) VALUES (
    v_old_plan.runner_id, v_old_plan.coach_id, v_old_plan.title, v_old_plan.goal,
    v_old_plan.current_level, v_old_plan.weekly_km_base, v_old_plan.days_per_week,
    v_old_plan.notes, v_old_plan.coach_message, 'active', now(), p_plan_id, v_next_tag
  )
  RETURNING id INTO v_new_plan_id;

  FOR v_week IN
    SELECT * FROM public.training_weeks WHERE plan_id = p_plan_id ORDER BY week_number
  LOOP
    INSERT INTO public.training_weeks (plan_id, week_number, week_type, focus, weekly_km_target, notes)
    VALUES (v_new_plan_id, v_week.week_number, v_week.week_type, v_week.focus, v_week.weekly_km_target, v_week.notes)
    RETURNING id INTO v_new_week_id;

    FOR v_session IN
      SELECT * FROM public.training_sessions WHERE week_id = v_week.id ORDER BY day_of_week
    LOOP
      SELECT elem INTO v_adapt
      FROM jsonb_array_elements(coalesce(p_adaptations, '[]'::jsonb)) elem
      WHERE elem->>'session_id' = v_session.id::text
      LIMIT 1;

      INSERT INTO public.training_sessions (
        week_id, day_of_week, session_type, title, distance_km, duration_min,
        pace_target, intensity, rpe_target, warmup_desc, main_desc, cooldown_desc,
        description, coach_notes, status, completed_at
      ) VALUES (
        v_new_week_id,
        v_session.day_of_week,
        coalesce(v_adapt->>'session_type', v_session.session_type),
        CASE WHEN v_adapt ? 'title'         THEN v_adapt->>'title'         ELSE v_session.title         END,
        CASE WHEN v_adapt ? 'distance_km'   THEN (v_adapt->>'distance_km')::numeric ELSE v_session.distance_km END,
        CASE WHEN v_adapt ? 'duration_min'  THEN (v_adapt->>'duration_min')::integer ELSE v_session.duration_min END,
        CASE WHEN v_adapt ? 'pace_target'   THEN v_adapt->>'pace_target'   ELSE v_session.pace_target   END,
        coalesce(v_adapt->>'intensity', v_session.intensity),
        CASE WHEN v_adapt ? 'rpe_target'    THEN (v_adapt->>'rpe_target')::integer ELSE v_session.rpe_target END,
        CASE WHEN v_adapt ? 'warmup_desc'   THEN v_adapt->>'warmup_desc'   ELSE v_session.warmup_desc   END,
        CASE WHEN v_adapt ? 'main_desc'     THEN v_adapt->>'main_desc'     ELSE v_session.main_desc     END,
        CASE WHEN v_adapt ? 'cooldown_desc' THEN v_adapt->>'cooldown_desc' ELSE v_session.cooldown_desc END,
        CASE WHEN v_adapt ? 'description'   THEN v_adapt->>'description'   ELSE v_session.description   END,
        v_session.coach_notes,
        v_session.status,
        v_session.completed_at
      );
    END LOOP;
  END LOOP;

  UPDATE public.plans SET status = 'archived', updated_at = now() WHERE id = p_plan_id;

  RETURN v_new_plan_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_adapt_plan(uuid, jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.fn_adapt_plan(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_adapt_plan(uuid, jsonb) TO service_role;

-- 045 — Derecho al Olvido / Derecho de Supresión (Ley 21.719 Art. 4)
-- fn_forget_runner v2: cierra fugas de PII/N2 en tablas sin CASCADE a runners
-- (web_registrations, legacy_web_registrations, event_winners).

create table if not exists public.gdpr_deletion_log (
  id           uuid primary key default gen_random_uuid(),
  runner_id    uuid not null,
  deleted_at   timestamptz not null default now(),
  requested_by uuid,
  reason       text,
  created_at   timestamptz not null default now()
);

alter table public.gdpr_deletion_log enable row level security;

drop policy if exists gdpr_deletion_log_admin_read on public.gdpr_deletion_log;
create policy gdpr_deletion_log_admin_read
  on public.gdpr_deletion_log
  for select to authenticated
  using (public.fn_is_admin_or_super());

revoke all on table public.gdpr_deletion_log from anon;

create or replace function public.fn_forget_runner(
  p_runner_id uuid,
  p_reason    text default 'Solicitud de supresión Art. 4 Ley 21.719'
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_email      text;
  v_deleted_at timestamptz;
  n_tokens     int;
  n_anamnesis  int;
  n_webregs    int;
  n_legacy     int;
  n_winners    int;
begin
  if not public.fn_is_admin_or_super() then
    raise exception 'Acceso denegado: se requiere rol de administrador (Ley 21.719 Art. 4).'
      using errcode = 'insufficient_privilege';
  end if;

  select email
    into v_email
    from public.runners
   where id = p_runner_id;

  if v_email is null then
    return jsonb_build_object(
      'ok',        false,
      'error',     'runner_not_found',
      'runner_id', p_runner_id
    );
  end if;

  -- 1. Purgar tokens (sin FK a runners, vinculados solo por email)
  delete from public.anamnesis_tokens
   where lower(runner_email) = lower(v_email);
  get diagnostics n_tokens = row_count;

  -- 2. Borrar anamnesis explicitamente para trazabilidad WAL pre-cascade
  delete from public.anamnesis
   where runner_id = p_runner_id
      or lower(runner_email) = lower(v_email);
  get diagnostics n_anamnesis = row_count;

  -- 3. Inscripciones web actuales (PII + condicion_medica N2, sin FK a runners)
  delete from public.web_registrations
   where lower(email) = lower(v_email);
  get diagnostics n_webregs = row_count;

  -- 4. Inscripciones legadas (FK SET NULL dejaba huerfanos con N2)
  delete from public.legacy_web_registrations
   where runner_id = p_runner_id;
  get diagnostics n_legacy = row_count;

  -- 5. Premios: anonimizar titular, conservar el codigo como registro de negocio
  update public.event_winners
     set nombre_externo = null,
         email_externo  = null
   where runner_id = p_runner_id
      or lower(email_externo) = lower(v_email);
  get diagnostics n_winners = row_count;

  -- 6. Borrar runner: CASCADE elimina plans, check_ins, health_alerts,
  --    scores IA, adherence_scores, session_results y la cadena completa
  delete from public.runners
   where id = p_runner_id;

  -- 7. Log de auditoria (sin PII, solo UUID)
  v_deleted_at := now();

  insert into public.gdpr_deletion_log (runner_id, deleted_at, requested_by, reason)
  values (p_runner_id, v_deleted_at, auth.uid(), p_reason);

  return jsonb_build_object(
    'ok',                  true,
    'deleted_at',          v_deleted_at,
    'runner_id',           p_runner_id,
    'purged',              jsonb_build_object(
      'anamnesis_tokens',          n_tokens,
      'anamnesis',                 n_anamnesis,
      'web_registrations',         n_webregs,
      'legacy_web_registrations',  n_legacy,
      'event_winners_anonimizados', n_winners
    )
  );

exception
  when others then
    return jsonb_build_object(
      'ok',        false,
      'error',     sqlerrm,
      'sqlstate',  sqlstate,
      'runner_id', p_runner_id
    );
end;
$$;

revoke all on function public.fn_forget_runner(uuid, text) from public, anon;
grant execute on function public.fn_forget_runner(uuid, text) to authenticated, service_role;

-- 064 — Remediación Pentest: revocación de grants anon sobre tablas PII/N2
-- H-1: web_registrations sin grants anon (flujo público via RPC definer).
-- H-2: anamnesis_tokens bloqueo absoluto anon (marcado used_at es trigger 055).
-- H-3: anamnesis solo INSERT anon (política anamnesis_public_submit, sin RETURNING).
-- H-4: TRUNCATE/REFERENCES/TRIGGER ignoran RLS: barrido global + default privileges.

revoke all on table public.web_registrations from anon;

revoke all on table public.anamnesis_tokens from anon;
drop policy if exists anamnesis_tokens_anon_mark_used on public.anamnesis_tokens;

revoke all on table public.anamnesis from anon;
grant insert on table public.anamnesis to anon;

revoke truncate, references, trigger on all tables in schema public from anon, authenticated;
alter default privileges in schema public
  revoke truncate, references, trigger on tables from anon, authenticated;

-- 065 — Derecho al Olvido v3: cierre de la capa de cuenta/social
--
-- AUDITORÍA DPO 2026-07-09 (segunda pasada): fn_forget_runner v2 (migración 045)
-- purga correctamente todo lo que cuelga de runners.id vía FK CASCADE, más
-- web_registrations / legacy_web_registrations / event_winners (sin FK, por
-- email). Pero ~23 tablas de la capa social/cuenta están vinculadas por
-- user_id (= auth.users.id, vía runners.user_id) y NO cuelgan de runners por
-- ninguna FK declarada: sobrevivían intactas a una "corredora olvidada"
-- (mensajes, posts, notificaciones, perfil social, transacciones de puntos...).
-- v3 captura runners.user_id ANTES del borrado y purga también esa capa.
--
-- Nota de diseño: NO se borra auth.users aquí (Supabase desaconseja DELETE SQL
-- directo sobre auth.* — riesgo de dejar caches/refresh tokens de GoTrue
-- inconsistentes). El resultado marca auth_account_purge_required=true y
-- devuelve el user_id para que el llamador complete el borrado de la cuenta
-- de acceso vía Admin API (auth.admin.deleteUser), igual que el patrón ya
-- usado por la función delete-account del repo.
--
-- Exclusiones deliberadas (no se tocan, requieren decisión de negocio/legal,
-- no técnica): audit_logs (trazabilidad de acciones admin sobre terceros),
-- reported_content (registros de moderación/confianza y seguridad),
-- training_sos_alerts (incidentes de seguridad en terreno — posible deber de
-- retención legal), gdpr_deletion_log (es el propio registro de la supresión).

create or replace function public.fn_forget_runner(
  p_runner_id uuid,
  p_reason    text default 'Solicitud de supresión Art. 4 Ley 21.719'
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_email      text;
  v_user_id    uuid;
  v_deleted_at timestamptz;
  n_tokens     int;
  n_anamnesis  int;
  n_webregs    int;
  n_legacy     int;
  n_winners    int;
  n_account    jsonb;
  c_activities int; c_ai_log int; c_channel_part int; c_checkins int;
  c_emo_checkins int; c_notifications int; c_point_tx int; c_post_likes int;
  c_reactivation int; c_reward_redemptions int; c_training_checkins int;
  c_training_group_members int; c_training_leaders int; c_training_surveys int;
  c_user_achievements int; c_user_onboarding int; c_user_roles int;
  c_feed_posts int; c_messages int; c_follows int; c_blocked int;
  c_referrals int; c_user_profiles int;
begin
  if not public.fn_is_admin_or_super() then
    raise exception 'Acceso denegado: se requiere rol de administrador (Ley 21.719 Art. 4).'
      using errcode = 'insufficient_privilege';
  end if;

  select email, user_id
    into v_email, v_user_id
    from public.runners
   where id = p_runner_id;

  if v_email is null then
    return jsonb_build_object(
      'ok',        false,
      'error',     'runner_not_found',
      'runner_id', p_runner_id
    );
  end if;

  -- 1. Purgar tokens (sin FK a runners, vinculados solo por email)
  delete from public.anamnesis_tokens
   where lower(runner_email) = lower(v_email);
  get diagnostics n_tokens = row_count;

  -- 2. Borrar anamnesis explícitamente para trazabilidad WAL pre-cascade
  delete from public.anamnesis
   where runner_id = p_runner_id
      or lower(runner_email) = lower(v_email);
  get diagnostics n_anamnesis = row_count;

  -- 3. Inscripciones web actuales (PII + condicion_medica N2, sin FK a runners)
  delete from public.web_registrations
   where lower(email) = lower(v_email);
  get diagnostics n_webregs = row_count;

  -- 4. Inscripciones legadas (FK SET NULL dejaba huérfanos con N2)
  delete from public.legacy_web_registrations
   where runner_id = p_runner_id;
  get diagnostics n_legacy = row_count;

  -- 5. Premios: anonimizar titular, conservar el código como registro de negocio
  update public.event_winners
     set nombre_externo = null,
         email_externo  = null
   where runner_id = p_runner_id
      or lower(email_externo) = lower(v_email);
  get diagnostics n_winners = row_count;

  -- 6. NUEVO v3 — capa de cuenta/social (vinculada por user_id, no por
  --    runner_id): estas tablas NO cuelgan de runners.id por FK y
  --    sobrevivirían al borrado de la fila runners si no se purgan aquí.
  if v_user_id is not null then
    delete from public.activities where user_id = v_user_id; get diagnostics c_activities = row_count;
    delete from public.ai_request_log where user_id = v_user_id; get diagnostics c_ai_log = row_count;
    delete from public.channel_participants where user_id = v_user_id; get diagnostics c_channel_part = row_count;
    delete from public.checkins where user_id = v_user_id; get diagnostics c_checkins = row_count;
    delete from public.emotional_checkins where user_id = v_user_id; get diagnostics c_emo_checkins = row_count;
    delete from public.notifications where user_id = v_user_id; get diagnostics c_notifications = row_count;
    delete from public.point_transactions where user_id = v_user_id; get diagnostics c_point_tx = row_count;
    delete from public.post_likes where user_id = v_user_id; get diagnostics c_post_likes = row_count;
    delete from public.reactivation_log where user_id = v_user_id; get diagnostics c_reactivation = row_count;
    delete from public.reward_redemptions where user_id = v_user_id; get diagnostics c_reward_redemptions = row_count;
    delete from public.training_checkins where user_id = v_user_id; get diagnostics c_training_checkins = row_count;
    delete from public.training_group_members where user_id = v_user_id; get diagnostics c_training_group_members = row_count;
    delete from public.training_leaders where user_id = v_user_id; get diagnostics c_training_leaders = row_count;
    delete from public.training_surveys where user_id = v_user_id; get diagnostics c_training_surveys = row_count;
    delete from public.user_achievements where user_id = v_user_id; get diagnostics c_user_achievements = row_count;
    delete from public.user_onboarding where user_id = v_user_id; get diagnostics c_user_onboarding = row_count;
    delete from public.user_roles where user_id = v_user_id; get diagnostics c_user_roles = row_count;
    delete from public.feed_posts where author_id = v_user_id; get diagnostics c_feed_posts = row_count;
    delete from public.messages where sender_id = v_user_id; get diagnostics c_messages = row_count;
    delete from public.follows where follower_id = v_user_id or following_id = v_user_id; get diagnostics c_follows = row_count;
    delete from public.blocked_users where blocker_id = v_user_id or blocked_id = v_user_id; get diagnostics c_blocked = row_count;
    delete from public.referrals where referrer_id = v_user_id or referred_id = v_user_id; get diagnostics c_referrals = row_count;
    delete from public.user_profiles where id = v_user_id; get diagnostics c_user_profiles = row_count;

    n_account := jsonb_build_object(
      'activities', c_activities, 'ai_request_log', c_ai_log,
      'channel_participants', c_channel_part, 'checkins', c_checkins,
      'emotional_checkins', c_emo_checkins, 'notifications', c_notifications,
      'point_transactions', c_point_tx, 'post_likes', c_post_likes,
      'reactivation_log', c_reactivation, 'reward_redemptions', c_reward_redemptions,
      'training_checkins', c_training_checkins,
      'training_group_members', c_training_group_members,
      'training_leaders', c_training_leaders, 'training_surveys', c_training_surveys,
      'user_achievements', c_user_achievements, 'user_onboarding', c_user_onboarding,
      'user_roles', c_user_roles, 'feed_posts', c_feed_posts, 'messages', c_messages,
      'follows', c_follows, 'blocked_users', c_blocked, 'referrals', c_referrals,
      'user_profiles', c_user_profiles
    );
  else
    n_account := jsonb_build_object('skipped', 'runner sin user_id vinculado (nunca tuvo cuenta app)');
  end if;

  -- 7. Borrar runner → CASCADE elimina plans, plan_check_ins, health_alerts,
  --    scores IA, adherence_scores, health_profiles, runner_profiles,
  --    assessments, session_results, partner_benefit_claims, training_weeks,
  --    training_sessions y la cadena completa.
  delete from public.runners
   where id = p_runner_id;

  -- 8. Log de auditoría (sin PII — solo UUID). Nunca se borra de aquí.
  v_deleted_at := now();

  insert into public.gdpr_deletion_log (runner_id, deleted_at, requested_by, reason)
  values (p_runner_id, v_deleted_at, auth.uid(), p_reason);

  return jsonb_build_object(
    'ok',                          true,
    'deleted_at',                  v_deleted_at,
    'runner_id',                   p_runner_id,
    'purged',                      jsonb_build_object(
      'anamnesis_tokens',           n_tokens,
      'anamnesis',                  n_anamnesis,
      'web_registrations',          n_webregs,
      'legacy_web_registrations',   n_legacy,
      'event_winners_anonimizados', n_winners,
      'cuenta_social',              n_account
    ),
    'auth_account_purge_required', (v_user_id is not null),
    'user_id_pendiente_borrado',   v_user_id,
    'nota', 'auth.users NO se borra aquí por diseño. Completar el borrado de la ' ||
            'credencial de acceso vía auth.admin.deleteUser(user_id) desde una ' ||
            'Edge Function con service_role, siguiendo el patrón de delete-account.'
  );

exception
  when others then
    return jsonb_build_object(
      'ok',        false,
      'error',     sqlerrm,
      'sqlstate',  sqlstate,
      'runner_id', p_runner_id
    );
end;
$$;

revoke all on function public.fn_forget_runner(uuid, text) from public, anon;
grant execute on function public.fn_forget_runner(uuid, text) to authenticated, service_role;

-- Comunidad: permitir designar lider de entrenamiento (coach/admin) y pacers
-- entre las inscritas reales (web_registrations) en vez de un catalogo aparte.

-- 1. training_leaders.role: admitir 'admin' ademas de 'coach'/'pacer'.
ALTER TABLE public.training_leaders DROP CONSTRAINT training_leaders_role_check;
ALTER TABLE public.training_leaders
  ADD CONSTRAINT training_leaders_role_check
  CHECK (role = ANY (ARRAY['coach'::text, 'pacer'::text, 'admin'::text]));

-- 2. training_pacers.pacer_id: retarget de wsr_pacers (catalogo vacio, muerto)
--    a web_registrations (inscritas reales). Tabla vacia hoy, sin datos que migrar.
ALTER TABLE public.training_pacers DROP CONSTRAINT training_pacers_pacer_id_fkey;
ALTER TABLE public.training_pacers
  ADD CONSTRAINT training_pacers_pacer_id_fkey
  FOREIGN KEY (pacer_id) REFERENCES public.web_registrations(id) ON DELETE CASCADE;

-- 3. Trigger: el pacer_id referenciado debe pertenecer al mismo training_id
--    (evita asignar como pacer a alguien inscrita en OTRO entrenamiento).
CREATE OR REPLACE FUNCTION public.fn_validate_training_pacer()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.web_registrations wr
    WHERE wr.id = NEW.pacer_id AND wr.training_id = NEW.training_id
  ) THEN
    RAISE EXCEPTION 'pacer_id debe corresponder a una inscripcion (web_registrations) del mismo training_id';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_validate_training_pacer ON public.training_pacers;
CREATE TRIGGER trg_validate_training_pacer
  BEFORE INSERT OR UPDATE ON public.training_pacers
  FOR EACH ROW EXECUTE FUNCTION public.fn_validate_training_pacer();

-- 4. Policies de escritura para staff (mismo patron que trainings_staff_manage).
CREATE POLICY "training_leaders_staff_manage" ON public.training_leaders
  FOR ALL TO authenticated
  USING (fn_is_admin_or_super() OR fn_is_coach())
  WITH CHECK (fn_is_admin_or_super() OR fn_is_coach());

CREATE POLICY "training_pacers_staff_manage" ON public.training_pacers
  FOR ALL TO authenticated
  USING (fn_is_admin_or_super() OR fn_is_coach())
  WITH CHECK (fn_is_admin_or_super() OR fn_is_coach());

-- 067 — Check-in tokenizado + consentimientos versionados (Ley 21.719)
-- (contenido idéntico a wsr-backend/supabase/migrations/067_checkin_tokens_and_consents.sql)

alter table public.runners
  add column if not exists acepta_marketing    boolean not null default false,
  add column if not exists autoriza_imagen     boolean not null default false,
  add column if not exists consent_version     text,
  add column if not exists consents_updated_at timestamptz;

comment on column public.runners.acepta_marketing is
  'Consentimiento OPCIONAL para compartir intereses con marcas auspiciadoras (Ley 21.719 arts. 12/15). Separado del consentimiento base.';
comment on column public.runners.autoriza_imagen is
