CREATE OR REPLACE FUNCTION public.fn_purge_runner_cascade(
  p_runner_id uuid,
  p_reason text,
  p_requested_by uuid
) RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email      text;
  v_user_id    uuid;
  v_deleted_at timestamptz;
  n_tokens     int; n_anamnesis int; n_webregs int; n_legacy int; n_winners int;
  n_account    jsonb;
  c_activities int; c_ai_log int; c_channel_part int; c_checkins int;
  c_emo_checkins int; c_notifications int; c_point_tx int; c_post_likes int;
  c_reactivation int; c_reward_redemptions int; c_training_checkins int;
  c_training_group_members int; c_training_leaders int; c_training_surveys int;
  c_user_achievements int; c_user_onboarding int; c_user_roles int;
  c_feed_posts int; c_messages int; c_follows int; c_blocked int;
  c_referrals int; c_user_profiles int;
begin
  select email, user_id into v_email, v_user_id
    from public.runners where id = p_runner_id;

  if v_email is null then
    return jsonb_build_object('ok', false, 'error', 'runner_not_found', 'runner_id', p_runner_id);
  end if;

  delete from public.anamnesis_tokens where lower(runner_email) = lower(v_email);
  get diagnostics n_tokens = row_count;

  delete from public.anamnesis where runner_id = p_runner_id or lower(runner_email) = lower(v_email);
  get diagnostics n_anamnesis = row_count;

  delete from public.web_registrations where lower(email) = lower(v_email);
  get diagnostics n_webregs = row_count;

  delete from public.legacy_web_registrations where runner_id = p_runner_id;
  get diagnostics n_legacy = row_count;

  update public.event_winners set nombre_externo = null, email_externo = null
   where runner_id = p_runner_id or lower(email_externo) = lower(v_email);
  get diagnostics n_winners = row_count;

  if v_user_id is not null then
    delete from public.activities where user_id = v_user_id; get diagnostics c_activities = row_count;
    delete from public.ai_request_log where user_id = v_user_id; get diagnostics c_ai_log = row_count;
    delete from public.channel_participants where user_id = v_user_id; get diagnostics c_channel_part = row_count;
    delete from public.checkins where user_id = v_user_id; get diagnostics c_checkins = row_count;
    delete from public.emotional_checkins where user_id = v_user_id; get diagnostics c_emo_checkins = row_count;
    delete from public.notifications where user_id = v_user_id; get diagnostics c_notifications = row_count;
    delete from public.point_transactions where user_id = v_user_id; get diagnostics c_point_tx = row_count;
    delete from public.post_likes where user_id = v_user_id; get diagnostics c_post_likes = row_count;
    delete from public.reactivation_log where user_id = v_user_id; get diagnostics c_reactivation = row_count;
    delete from public.reward_redemptions where user_id = v_user_id; get diagnostics c_reward_redemptions = row_count;
    delete from public.training_checkins where user_id = v_user_id; get diagnostics c_training_checkins = row_count;
    delete from public.training_group_members where user_id = v_user_id; get diagnostics c_training_group_members = row_count;
    delete from public.training_leaders where user_id = v_user_id; get diagnostics c_training_leaders = row_count;
    delete from public.training_surveys where user_id = v_user_id; get diagnostics c_training_surveys = row_count;
    delete from public.user_achievements where user_id = v_user_id; get diagnostics c_user_achievements = row_count;
    delete from public.user_onboarding where user_id = v_user_id; get diagnostics c_user_onboarding = row_count;
    delete from public.user_roles where user_id = v_user_id; get diagnostics c_user_roles = row_count;
    delete from public.feed_posts where author_id = v_user_id; get diagnostics c_feed_posts = row_count;
    delete from public.messages where sender_id = v_user_id; get diagnostics c_messages = row_count;
    delete from public.follows where follower_id = v_user_id or following_id = v_user_id; get diagnostics c_follows = row_count;
    delete from public.blocked_users where blocker_id = v_user_id or blocked_id = v_user_id; get diagnostics c_blocked = row_count;
    delete from public.referrals where referrer_id = v_user_id or referred_id = v_user_id; get diagnostics c_referrals = row_count;
    delete from public.user_profiles where id = v_user_id; get diagnostics c_user_profiles = row_count;

    n_account := jsonb_build_object(
      'activities', c_activities, 'ai_request_log', c_ai_log,
      'channel_participants', c_channel_part, 'checkins', c_checkins,
      'emotional_checkins', c_emo_checkins, 'notifications', c_notifications,
      'point_transactions', c_point_tx, 'post_likes', c_post_likes,
      'reactivation_log', c_reactivation, 'reward_redemptions', c_reward_redemptions,
      'training_checkins', c_training_checkins,
      'training_group_members', c_training_group_members,
      'training_leaders', c_training_leaders, 'training_surveys', c_training_surveys,
      'user_achievements', c_user_achievements, 'user_onboarding', c_user_onboarding,
      'user_roles', c_user_roles, 'feed_posts', c_feed_posts, 'messages', c_messages,
      'follows', c_follows, 'blocked_users', c_blocked, 'referrals', c_referrals,
      'user_profiles', c_user_profiles
    );
  else
    n_account := jsonb_build_object('skipped', 'runner sin user_id vinculado (nunca tuvo cuenta app)');
  end if;

  delete from public.runners where id = p_runner_id;

  v_deleted_at := now();
  insert into public.gdpr_deletion_log (runner_id, deleted_at, requested_by, reason)
  values (p_runner_id, v_deleted_at, p_requested_by, p_reason);

  return jsonb_build_object(
    'ok', true, 'deleted_at', v_deleted_at, 'runner_id', p_runner_id,
    'purged', jsonb_build_object(
      'anamnesis_tokens', n_tokens, 'anamnesis', n_anamnesis,
      'web_registrations', n_webregs, 'legacy_web_registrations', n_legacy,
      'event_winners_anonimizados', n_winners, 'cuenta_social', n_account),
    'auth_account_purge_required', (v_user_id is not null),
    'user_id_pendiente_borrado', v_user_id
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'sqlstate', sqlstate, 'runner_id', p_runner_id);
end;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_purge_runner_cascade(uuid, text, uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.fn_forget_runner(
  p_runner_id uuid,
  p_reason text DEFAULT 'Solicitud de supresión Art. 4 Ley 21.719'::text
) RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.fn_is_admin_or_super() then
    raise exception 'Acceso denegado: se requiere rol de administrador (Ley 21.719 Art. 4).'
      using errcode = 'insufficient_privilege';
  end if;
  return public.fn_purge_runner_cascade(p_runner_id, p_reason, auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_forget_my_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_runner_id uuid;
begin
  if auth.uid() is null then
    raise exception 'No autenticada' using errcode = '42501';
  end if;

  select id into v_runner_id from public.runners where user_id = auth.uid();

  if v_runner_id is null then
    return jsonb_build_object('ok', true, 'note', 'sin_runner_vinculado', 'user_id', auth.uid());
  end if;

  return public.fn_purge_runner_cascade(
    v_runner_id,
    'Autoservicio: eliminación de cuenta in-app (Apple 5.1.1(v) / Art. 4 Ley 21.719)',
    auth.uid()
  );
end;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_forget_my_account() FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_forget_my_account() TO authenticated;

CREATE OR REPLACE FUNCTION public.wsr_confirmar_inscripcion_web()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key              text;
  v_primer_nombre    text;
  v_titulo           text;
  v_titulo_cap       text;
  v_fecha_hora       timestamptz;
  v_ubicacion        text;
  v_ubicacion_texto  text;
  v_latitud          float8;
  v_longitud         float8;
  v_dia_semana       text;
  v_dia_num          text;
  v_mes              text;
  v_anio             text;
  v_hora             text;
  v_fecha_txt        text;
  v_fila_ubicacion   text;
  v_cta_url          text;
  v_nota_encuentro   text;
  v_html             text;
  v_html_bienvenida  text;
  v_dow              int;
  v_mon              int;
  v_es_primera       boolean;
BEGIN
  IF NEW.estado_reserva <> 'confirmada' THEN RETURN NEW; END IF;

  SELECT value INTO v_key FROM wsr_config WHERE key = 'resend_api_key';
  IF v_key IS NULL OR v_key = 'PEGA_TU_API_KEY_DE_RESEND_AQUI' THEN RETURN NEW; END IF;
  IF NEW.email IS NULL THEN RETURN NEW; END IF;

  SELECT title, scheduled_at, location_name, location_detail, latitude, longitude
  INTO v_titulo, v_fecha_hora, v_ubicacion, v_ubicacion_texto, v_latitud, v_longitud
  FROM trainings WHERE id = NEW.training_id;

  v_primer_nombre := split_part(trim(coalesce(NEW.nombre, 'Corredora')), ' ', 1);
  v_titulo_cap    := upper(left(v_titulo, 1)) || substring(v_titulo from 2);

  v_dow := extract(dow  FROM v_fecha_hora AT TIME ZONE 'America/Santiago');
  v_mon := extract(month FROM v_fecha_hora AT TIME ZONE 'America/Santiago');
  v_dia_num := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'DD');
  v_anio    := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'YYYY');
  v_hora    := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'HH24:MI');

  v_dia_semana := CASE v_dow
    WHEN 0 THEN 'Domingo'  WHEN 1 THEN 'Lunes'   WHEN 2 THEN 'Martes'
    WHEN 3 THEN 'Miércoles' WHEN 4 THEN 'Jueves'  WHEN 5 THEN 'Viernes'
    WHEN 6 THEN 'Sábado'
  END;
  v_mes := CASE v_mon
    WHEN 1  THEN 'enero'     WHEN 2  THEN 'febrero'   WHEN 3  THEN 'marzo'
    WHEN 4  THEN 'abril'     WHEN 5  THEN 'mayo'       WHEN 6  THEN 'junio'
    WHEN 7  THEN 'julio'     WHEN 8  THEN 'agosto'     WHEN 9  THEN 'septiembre'
    WHEN 10 THEN 'octubre'   WHEN 11 THEN 'noviembre'  WHEN 12 THEN 'diciembre'
  END;

  v_fecha_txt      := v_dia_semana || ' ' || v_dia_num || ' de ' || v_mes || ' de ' || v_anio;
  v_fila_ubicacion := CASE WHEN v_ubicacion IS NOT NULL
    THEN '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">📍 ' || v_ubicacion || '</td></tr>'
    ELSE ''
  END;

  IF v_latitud IS NOT NULL AND v_longitud IS NOT NULL THEN
    v_cta_url        := 'https://www.google.com/maps?q=' || v_latitud::text || ',' || v_longitud::text;
    v_nota_encuentro := coalesce(v_ubicacion_texto, v_ubicacion, 'Te esperamos en el punto marcado en el mapa.');
  ELSE
    v_cta_url        := 'https://www.instagram.com/woman_social_run/';
    v_nota_encuentro := 'El lugar exacto se confirma por Instagram antes del entrenamiento. Síguenos para no perderte nada.';
  END IF;

  -- ¿Es la primera reserva confirmada de este email en toda la historia?
  SELECT NOT EXISTS (
    SELECT 1 FROM web_registrations
    WHERE email = NEW.email
      AND estado_reserva = 'confirmada'
      AND id <> NEW.id
  ) INTO v_es_primera;

  IF v_es_primera THEN
    v_html_bienvenida :=
      '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
      '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
      '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
      '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
      '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
      '<div style="height:3px;background:linear-gradient(90deg,#D9488C,#F08EC0,#C9A66B);"></div>' ||
      '<div style="padding:48px 40px 28px;text-align:center;">' ||
      '<p style="margin:0 0 14px;font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:#D9488C;opacity:.8;">Bienvenida</p>' ||
      '<h1 style="margin:0;font-family:Georgia,serif;font-size:2.1rem;font-weight:400;color:#3D1020;line-height:1.15;">Hola, ' || v_primer_nombre || '.</h1>' ||
      '</div>' ||
      '<div style="margin:0 40px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,72,140,.2),transparent);"></div>' ||
      '<div style="padding:28px 40px 40px;">' ||
      '<p style="margin:0 0 16px;font-size:1rem;color:#5C3248;line-height:1.75;">Nos alegra mucho que estés aquí. Woman Social Run es una comunidad de mujeres que corren juntas, a su propio ritmo, sin presión ni marcas de tiempo.</p>' ||
      '<p style="margin:0 0 28px;font-size:1rem;color:#5C3248;line-height:1.75;">En cada encuentro buscamos lo mismo: movimiento, compañía y presencia. Pronto te avisaremos de los próximos entrenamientos.</p>' ||
      '<div style="text-align:center;margin:8px 0;">' ||
      '<a href="https://www.instagram.com/woman_social_run/" style="display:inline-block;padding:14px 34px;background:#D9488C;color:#fff;text-decoration:none;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-radius:999px;font-weight:500;">Síguenos en Instagram →</a>' ||
      '</div></div></div>' ||
      '<div style="text-align:center;padding:28px 16px 0;font-size:.68rem;color:#B07A90;letter-spacing:.06em;line-height:1.8;">' ||
      '<p style="margin:0;">Woman Social Run · Santiago, Chile</p>' ||
      '<p style="margin:4px 0 0;opacity:.65;">Recibiste este correo porque te registraste en WSR.</p>' ||
      '</div></div></body></html>';

    PERFORM net.http_post(
      url     := 'https://api.resend.com/emails',
      headers := jsonb_build_object(
        'Content-Type',  'application/json',
        'Authorization', 'Bearer ' || v_key
      ),
      body := jsonb_build_object(
        'from',    'Woman Social Run <felipe@womansocialrun.cl>',
        'to',      ARRAY[NEW.email],
        'subject', 'Bienvenida a Woman Social Run ·',
        'html',    v_html_bienvenida
      )
    );
  END IF;

  v_html :=
    '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
    '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
    '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
    '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
    '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
    '<div style="height:3px;background:linear-gradient(90deg,#D9488C,#F08EC0,#C9A66B);"></div>' ||
    '<div style="padding:48px 40px 28px;text-align:center;">' ||
    '<p style="margin:0 0 14px;font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:#D9488C;opacity:.8;">Inscripción confirmada</p>' ||
    '<h1 style="margin:0;font-family:Georgia,serif;font-size:2.1rem;font-weight:400;color:#3D1020;line-height:1.15;">¡Tu lugar está<br/>confirmado, ' || v_primer_nombre || '!</h1>' ||
    '</div>' ||
    '<div style="margin:0 40px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,72,140,.2),transparent);"></div>' ||
    '<div style="padding:28px 40px 40px;">' ||
    '<p style="margin:0 0 22px;font-size:1rem;color:#5C3248;line-height:1.75;">Te esperamos en el siguiente entrenamiento:</p>' ||
    '<div style="background:#FFF5FB;border:1px solid #FFD1F1;border-left:3px solid #D9488C;border-radius:4px;padding:22px 22px 18px;">' ||
    '<p style="margin:0 0 12px;font-family:Georgia,serif;font-size:1.2rem;font-weight:400;color:#3D1020;line-height:1.3;">' || v_titulo_cap || '</p>' ||
    '<table style="border-collapse:collapse;width:100%;">' ||
    '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">📅 ' || v_fecha_txt || '</td></tr>' ||
    '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">🕐 ' || v_hora || ' hrs</td></tr>' ||
    v_fila_ubicacion ||
    '</table></div>' ||
    '<div style="margin:22px 0 0;padding:16px 18px;background:#FFF9FB;border:1px solid #FFE6F4;border-radius:4px;">' ||
    '<p style="margin:0;font-size:.875rem;color:#7B4F60;line-height:1.7;"><strong style="color:#5C3248;display:block;margin-bottom:3px;">📍 Punto de encuentro</strong>' || v_nota_encuentro || '</p>' ||
    '</div>' ||
    '<div style="text-align:center;margin:32px 0 8px;">' ||
    '<a href="' || v_cta_url || '" style="display:inline-block;padding:14px 34px;background:#D9488C;color:#fff;text-decoration:none;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-radius:999px;font-weight:500;">Ver punto de encuentro →</a>' ||
    '</div></div></div>' ||
    '<div style="text-align:center;padding:28px 16px 0;font-size:.68rem;color:#B07A90;letter-spacing:.06em;line-height:1.8;">' ||
    '<p style="margin:0;">Woman Social Run · Santiago, Chile</p>' ||
    '<p style="margin:4px 0 0;opacity:.65;">Recibiste este correo porque te inscribiste en un entrenamiento WSR.</p>' ||
    '</div></div></body></html>';

  PERFORM net.http_post(
    url     := 'https://api.resend.com/emails',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object(
      'from',    'Woman Social Run <felipe@womansocialrun.cl>',
      'to',      ARRAY[NEW.email],
      'subject', '¡Estás inscrita! ' || v_titulo_cap,
      'html',    v_html
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'wsr_confirmar_inscripcion_web: % (training_id=%, email=%)', SQLERRM, NEW.training_id, NEW.email;
  RETURN NEW;
END;
$function$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Correo de bienvenida al registrarse en la comunidad (tabla runners)
-- ═══════════════════════════════════════════════════════════════════════════
-- Hasta ahora, quienes se registraban vía el formulario de comunidad
-- (Inscripcion.tsx → api/save-profile.ts, que hace INSERT en runners) no
-- recibían ningún correo: no existía trigger AFTER INSERT en runners, y la
-- Edge Function enviar-bienvenida (escrita para esto) nunca quedó conectada
-- a un Database Webhook. Este trigger cierra ese hueco replicando el patrón
-- ya probado de wsr_confirmar_inscripcion_web (081_web_registration_welcome_email.sql).
--
-- Para no duplicar la bienvenida a quien ya la recibió por inscribirse antes
-- a un entrenamiento, este trigger se salta el envío si el email ya tiene una
-- reserva confirmada en web_registrations. Se agrega la verificación simétrica
-- en wsr_confirmar_inscripcion_web para que tampoco duplique si la corredora
-- ya tenía perfil en runners antes de esa inscripción.

CREATE OR REPLACE FUNCTION public.wsr_enviar_bienvenida_runner()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_key           text;
  v_nombre        text;
  v_html          text;
  v_ya_bienvenida boolean;
BEGIN
  SELECT value INTO v_key FROM wsr_config WHERE key = 'resend_api_key';
  IF v_key IS NULL OR v_key = 'PEGA_TU_API_KEY_DE_RESEND_AQUI' THEN RETURN NEW; END IF;
  IF NEW.email IS NULL THEN RETURN NEW; END IF;

  -- Ya recibió la bienvenida al inscribirse antes a un entrenamiento.
  SELECT EXISTS (
    SELECT 1 FROM web_registrations
    WHERE email = NEW.email AND estado_reserva = 'confirmada'
  ) INTO v_ya_bienvenida;
  IF v_ya_bienvenida THEN RETURN NEW; END IF;

  v_nombre := split_part(trim(coalesce(NEW.nombre_apellido, 'Corredora')), ' ', 1);

  v_html :=
    '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
    '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
    '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
    '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
    '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
    '<div style="height:3px;background:linear-gradient(90deg,#D9488C,#F08EC0,#C9A66B);"></div>' ||
    '<div style="padding:48px 40px 28px;text-align:center;">' ||
    '<p style="margin:0 0 14px;font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:#D9488C;opacity:.8;">Bienvenida</p>' ||
    '<h1 style="margin:0;font-family:Georgia,serif;font-size:2.1rem;font-weight:400;color:#3D1020;line-height:1.15;">Hola, ' || v_nombre || '.</h1>' ||
    '</div>' ||
    '<div style="margin:0 40px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,72,140,.2),transparent);"></div>' ||
    '<div style="padding:28px 40px 40px;">' ||
    '<p style="margin:0 0 16px;font-size:1rem;color:#5C3248;line-height:1.75;">Nos alegra mucho que estés aquí. Woman Social Run es una comunidad de mujeres que corren juntas, a su propio ritmo, sin presión ni marcas de tiempo.</p>' ||
    '<p style="margin:0 0 28px;font-size:1rem;color:#5C3248;line-height:1.75;">En cada encuentro buscamos lo mismo: movimiento, compañía y presencia. Pronto te avisaremos de los próximos entrenamientos.</p>' ||
    '<div style="text-align:center;margin:8px 0;">' ||
    '<a href="https://www.instagram.com/woman_social_run/" style="display:inline-block;padding:14px 34px;background:#D9488C;color:#fff;text-decoration:none;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-radius:999px;font-weight:500;">Síguenos en Instagram →</a>' ||
    '</div></div></div>' ||
    '<div style="text-align:center;padding:28px 16px 0;font-size:.68rem;color:#B07A90;letter-spacing:.06em;line-height:1.8;">' ||
    '<p style="margin:0;">Woman Social Run · Santiago, Chile</p>' ||
    '<p style="margin:4px 0 0;opacity:.65;">Recibiste este correo porque te registraste en WSR.</p>' ||
    '</div></div></body></html>';

  PERFORM net.http_post(
    url     := 'https://api.resend.com/emails',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object(
      'from',    'Woman Social Run <felipe@womansocialrun.cl>',
      'to',      ARRAY[NEW.email],
      'subject', 'Bienvenida a Woman Social Run ·',
      'html',    v_html
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'wsr_enviar_bienvenida_runner: % (email=%)', SQLERRM, NEW.email;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS wsr_on_runner_insert_bienvenida ON public.runners;
CREATE TRIGGER wsr_on_runner_insert_bienvenida
  AFTER INSERT ON public.runners
  FOR EACH ROW
  EXECUTE FUNCTION wsr_enviar_bienvenida_runner();


-- ── Guardar simetría: no duplicar bienvenida si ya existía perfil en runners ──
CREATE OR REPLACE FUNCTION public.wsr_confirmar_inscripcion_web()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_key              text;
  v_primer_nombre    text;
  v_titulo           text;
  v_titulo_cap       text;
  v_fecha_hora       timestamptz;
  v_ubicacion        text;
  v_ubicacion_texto  text;
  v_latitud          float8;
  v_longitud         float8;
  v_dia_semana       text;
  v_dia_num          text;
  v_mes              text;
  v_anio             text;
  v_hora             text;
  v_fecha_txt        text;
  v_fila_ubicacion   text;
  v_cta_url          text;
  v_nota_encuentro   text;
  v_html             text;
  v_html_bienvenida  text;
  v_dow              int;
  v_mon              int;
  v_es_primera       boolean;
BEGIN
  IF NEW.estado_reserva <> 'confirmada' THEN RETURN NEW; END IF;

  SELECT value INTO v_key FROM wsr_config WHERE key = 'resend_api_key';
  IF v_key IS NULL OR v_key = 'PEGA_TU_API_KEY_DE_RESEND_AQUI' THEN RETURN NEW; END IF;
  IF NEW.email IS NULL THEN RETURN NEW; END IF;

  SELECT title, scheduled_at, location_name, location_detail, latitude, longitude
  INTO v_titulo, v_fecha_hora, v_ubicacion, v_ubicacion_texto, v_latitud, v_longitud
  FROM trainings WHERE id = NEW.training_id;

  v_primer_nombre := split_part(trim(coalesce(NEW.nombre, 'Corredora')), ' ', 1);
  v_titulo_cap    := upper(left(v_titulo, 1)) || substring(v_titulo from 2);

  v_dow := extract(dow  FROM v_fecha_hora AT TIME ZONE 'America/Santiago');
  v_mon := extract(month FROM v_fecha_hora AT TIME ZONE 'America/Santiago');
  v_dia_num := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'DD');
  v_anio    := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'YYYY');
  v_hora    := to_char(v_fecha_hora AT TIME ZONE 'America/Santiago', 'HH24:MI');

  v_dia_semana := CASE v_dow
    WHEN 0 THEN 'Domingo'  WHEN 1 THEN 'Lunes'   WHEN 2 THEN 'Martes'
    WHEN 3 THEN 'Miércoles' WHEN 4 THEN 'Jueves'  WHEN 5 THEN 'Viernes'
    WHEN 6 THEN 'Sábado'
  END;
  v_mes := CASE v_mon
    WHEN 1  THEN 'enero'     WHEN 2  THEN 'febrero'   WHEN 3  THEN 'marzo'
    WHEN 4  THEN 'abril'     WHEN 5  THEN 'mayo'       WHEN 6  THEN 'junio'
    WHEN 7  THEN 'julio'     WHEN 8  THEN 'agosto'     WHEN 9  THEN 'septiembre'
    WHEN 10 THEN 'octubre'   WHEN 11 THEN 'noviembre'  WHEN 12 THEN 'diciembre'
  END;

  v_fecha_txt      := v_dia_semana || ' ' || v_dia_num || ' de ' || v_mes || ' de ' || v_anio;
  v_fila_ubicacion := CASE WHEN v_ubicacion IS NOT NULL
    THEN '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">📍 ' || v_ubicacion || '</td></tr>'
    ELSE ''
  END;

  IF v_latitud IS NOT NULL AND v_longitud IS NOT NULL THEN
    v_cta_url        := 'https://www.google.com/maps?q=' || v_latitud::text || ',' || v_longitud::text;
    v_nota_encuentro := coalesce(v_ubicacion_texto, v_ubicacion, 'Te esperamos en el punto marcado en el mapa.');
  ELSE
    v_cta_url        := 'https://www.instagram.com/woman_social_run/';
    v_nota_encuentro := 'El lugar exacto se confirma por Instagram antes del entrenamiento. Síguenos para no perderte nada.';
  END IF;

  -- ¿Es la primera reserva confirmada de este email en toda la historia, Y no
  -- recibió ya la bienvenida por tener perfil de comunidad (runners) previo?
  SELECT
    NOT EXISTS (
      SELECT 1 FROM web_registrations
      WHERE email = NEW.email AND estado_reserva = 'confirmada' AND id <> NEW.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM runners WHERE email = NEW.email
    )
  INTO v_es_primera;

  IF v_es_primera THEN
    v_html_bienvenida :=
      '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
      '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
      '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
      '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
      '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
      '<div style="height:3px;background:linear-gradient(90deg,#D9488C,#F08EC0,#C9A66B);"></div>' ||
      '<div style="padding:48px 40px 28px;text-align:center;">' ||
      '<p style="margin:0 0 14px;font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:#D9488C;opacity:.8;">Bienvenida</p>' ||
      '<h1 style="margin:0;font-family:Georgia,serif;font-size:2.1rem;font-weight:400;color:#3D1020;line-height:1.15;">Hola, ' || v_primer_nombre || '.</h1>' ||
      '</div>' ||
      '<div style="margin:0 40px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,72,140,.2),transparent);"></div>' ||
      '<div style="padding:28px 40px 40px;">' ||
      '<p style="margin:0 0 16px;font-size:1rem;color:#5C3248;line-height:1.75;">Nos alegra mucho que estés aquí. Woman Social Run es una comunidad de mujeres que corren juntas, a su propio ritmo, sin presión ni marcas de tiempo.</p>' ||
      '<p style="margin:0 0 28px;font-size:1rem;color:#5C3248;line-height:1.75;">En cada encuentro buscamos lo mismo: movimiento, compañía y presencia. Pronto te avisaremos de los próximos entrenamientos.</p>' ||
      '<div style="text-align:center;margin:8px 0;">' ||
      '<a href="https://www.instagram.com/woman_social_run/" style="display:inline-block;padding:14px 34px;background:#D9488C;color:#fff;text-decoration:none;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-radius:999px;font-weight:500;">Síguenos en Instagram →</a>' ||
      '</div></div></div>' ||
      '<div style="text-align:center;padding:28px 16px 0;font-size:.68rem;color:#B07A90;letter-spacing:.06em;line-height:1.8;">' ||
      '<p style="margin:0;">Woman Social Run · Santiago, Chile</p>' ||
      '<p style="margin:4px 0 0;opacity:.65;">Recibiste este correo porque te registraste en WSR.</p>' ||
      '</div></div></body></html>';

    PERFORM net.http_post(
      url     := 'https://api.resend.com/emails',
      headers := jsonb_build_object(
        'Content-Type',  'application/json',
        'Authorization', 'Bearer ' || v_key
      ),
      body := jsonb_build_object(
        'from',    'Woman Social Run <felipe@womansocialrun.cl>',
        'to',      ARRAY[NEW.email],
        'subject', 'Bienvenida a Woman Social Run ·',
        'html',    v_html_bienvenida
      )
    );
  END IF;

  v_html :=
    '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
    '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
    '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
    '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
    '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
    '<div style="height:3px;background:linear-gradient(90deg,#D9488C,#F08EC0,#C9A66B);"></div>' ||
    '<div style="padding:48px 40px 28px;text-align:center;">' ||
    '<p style="margin:0 0 14px;font-size:9px;letter-spacing:.32em;text-transform:uppercase;color:#D9488C;opacity:.8;">Inscripción confirmada</p>' ||
    '<h1 style="margin:0;font-family:Georgia,serif;font-size:2.1rem;font-weight:400;color:#3D1020;line-height:1.15;">¡Tu lugar está<br/>confirmado, ' || v_primer_nombre || '!</h1>' ||
    '</div>' ||
    '<div style="margin:0 40px;height:1px;background:linear-gradient(90deg,transparent,rgba(217,72,140,.2),transparent);"></div>' ||
    '<div style="padding:28px 40px 40px;">' ||
    '<p style="margin:0 0 22px;font-size:1rem;color:#5C3248;line-height:1.75;">Te esperamos en el siguiente entrenamiento:</p>' ||
    '<div style="background:#FFF5FB;border:1px solid #FFD1F1;border-left:3px solid #D9488C;border-radius:4px;padding:22px 22px 18px;">' ||
    '<p style="margin:0 0 12px;font-family:Georgia,serif;font-size:1.2rem;font-weight:400;color:#3D1020;line-height:1.3;">' || v_titulo_cap || '</p>' ||
    '<table style="border-collapse:collapse;width:100%;">' ||
    '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">📅 ' || v_fecha_txt || '</td></tr>' ||
    '<tr><td style="padding:5px 0;font-size:.875rem;color:#7B4F60;">🕐 ' || v_hora || ' hrs</td></tr>' ||
    v_fila_ubicacion ||
    '</table></div>' ||
    '<div style="margin:22px 0 0;padding:16px 18px;background:#FFF9FB;border:1px solid #FFE6F4;border-radius:4px;">' ||
    '<p style="margin:0;font-size:.875rem;color:#7B4F60;line-height:1.7;"><strong style="color:#5C3248;display:block;margin-bottom:3px;">📍 Punto de encuentro</strong>' || v_nota_encuentro || '</p>' ||
    '</div>' ||
    '<div style="text-align:center;margin:32px 0 8px;">' ||
    '<a href="' || v_cta_url || '" style="display:inline-block;padding:14px 34px;background:#D9488C;color:#fff;text-decoration:none;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-radius:999px;font-weight:500;">Ver punto de encuentro →</a>' ||
    '</div></div></div>' ||
    '<div style="text-align:center;padding:28px 16px 0;font-size:.68rem;color:#B07A90;letter-spacing:.06em;line-height:1.8;">' ||
    '<p style="margin:0;">Woman Social Run · Santiago, Chile</p>' ||
    '<p style="margin:4px 0 0;opacity:.65;">Recibiste este correo porque te inscribiste en un entrenamiento WSR.</p>' ||
    '</div></div></body></html>';

  PERFORM net.http_post(
    url     := 'https://api.resend.com/emails',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object(
      'from',    'Woman Social Run <felipe@womansocialrun.cl>',
      'to',      ARRAY[NEW.email],
      'subject', '¡Estás inscrita! ' || v_titulo_cap,
      'html',    v_html
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'wsr_confirmar_inscripcion_web: % (training_id=%, email=%)', SQLERRM, NEW.training_id, NEW.email;
  RETURN NEW;
END;
$function$;

create table public.marcas_patrocinadoras (
  id uuid primary key default gen_random_uuid(),
  nombre text not null,
  usuario_instagram text not null,
  activa boolean not null default true,
  creado_en timestamptz not null default now(),
  actualizado_en timestamptz not null default now(),
  constraint marcas_patrocinadoras_nombre_check check (btrim(nombre) <> ''),
  constraint marcas_patrocinadoras_usuario_check check (btrim(usuario_instagram) <> '')
);

comment on table public.marcas_patrocinadoras is
  'Roster de marcas patrocinadoras (nombre + @usuario de Instagram) para preseleccionar en el Informe de Marca, en vez de reingresarlas cada vez. Administrado directamente por el admin desde el cliente.';

create unique index marcas_patrocinadoras_usuario_unico
  on public.marcas_patrocinadoras (lower(btrim(usuario_instagram)));

create index marcas_patrocinadoras_activa_idx
  on public.marcas_patrocinadoras (activa) where activa;

create or replace function public.fn_set_actualizado_en()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  new.actualizado_en = now();
  return new;
end;
$$;

create trigger marcas_patrocinadoras_actualizado_en
  before update on public.marcas_patrocinadoras
  for each row execute function public.fn_set_actualizado_en();

alter table public.marcas_patrocinadoras enable row level security;

create policy "Admin lee marcas patrocinadoras"
  on public.marcas_patrocinadoras for select to authenticated
  using (public.fn_is_admin_or_super());

create policy "Admin crea marcas patrocinadoras"
  on public.marcas_patrocinadoras for insert to authenticated
  with check (public.fn_is_admin_or_super());

create policy "Admin edita marcas patrocinadoras"
  on public.marcas_patrocinadoras for update to authenticated
  using (public.fn_is_admin_or_super())
  with check (public.fn_is_admin_or_super());

revoke all on public.marcas_patrocinadoras from anon, public;
grant select, insert, update on public.marcas_patrocinadoras to authenticated;
grant all on public.marcas_patrocinadoras to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- Vinculación alumna↔coach + notificaciones por correo (check-in / alerta)
-- ═══════════════════════════════════════════════════════════════════════════
-- Cuando Laura, Gabriela o Felipe generan un plan, plans.coach_id ya queda
-- poblado con el uid del coach (api/generate-plan.ts). Pero el RLS que filtra
-- qué ve un coach en el panel (plan_check_ins_coach_read, health_alerts_*,
-- anamnesis_coach_read, etc.) depende de runners.coach_id, no de
-- plans.coach_id — y nada sincronizaba esa columna. Este archivo:
--
--   1. Sincroniza runners.coach_id cada vez que se genera/edita un plan
--      (gana siempre el coach del plan más reciente).
--   2. Aplica esa misma regla a los datos históricos (backfill).
--   3. Envía un correo de rutina al coach responsable en cada check-in.
--   4. Envía un correo urgente al coach responsable en cada alerta de salud
--      (dolor, cumplimiento o adherencia — los tres orígenes insertan con
--      runner_id directo).
--
-- Mismo patrón que 081/084: función SECURITY DEFINER + net.http_post directo
-- a Resend, api key desde wsr_config, EXCEPTION WHEN OTHERS para que un fallo
-- de correo jamás bloquee el check-in de la alumna ni la creación de la alerta.

-- ── 1. Sincronización runners.coach_id ← plans.coach_id ──────────────────────

CREATE OR REPLACE FUNCTION public.wsr_sync_runner_coach()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.coach_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.runners
     SET coach_id = NEW.coach_id
   WHERE id = NEW.runner_id
     AND coach_id IS DISTINCT FROM NEW.coach_id;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'wsr_sync_runner_coach: % (plan_id=%, runner_id=%)', SQLERRM, NEW.id, NEW.runner_id;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS wsr_on_plan_sync_runner_coach ON public.plans;
CREATE TRIGGER wsr_on_plan_sync_runner_coach
  AFTER INSERT OR UPDATE OF coach_id ON public.plans
  FOR EACH ROW
  EXECUTE FUNCTION public.wsr_sync_runner_coach();

-- ── 2. Backfill: alumnas que ya tienen plan hoy ───────────────────────────────

UPDATE public.runners r
   SET coach_id = latest.coach_id
  FROM (
    SELECT DISTINCT ON (runner_id) runner_id, coach_id
      FROM public.plans
     WHERE coach_id IS NOT NULL
     ORDER BY runner_id, created_at DESC
  ) latest
 WHERE r.id = latest.runner_id
   AND r.coach_id IS DISTINCT FROM latest.coach_id;

-- ── 3. Helper: email del coach responsable de una alumna ─────────────────────

CREATE OR REPLACE FUNCTION public.wsr_coach_email_for_runner(p_runner_id uuid)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT au.email
    FROM public.runners r
    JOIN auth.users au ON au.id = r.coach_id
   WHERE r.id = p_runner_id;
$function$;

-- ── 4. Correo de rutina: check-in nuevo ───────────────────────────────────────

CREATE OR REPLACE FUNCTION public.wsr_notify_coach_checkin()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_key         text;
  v_coach_email text;
  v_nombre      text;
  v_fecha_txt   text;
  v_dolor_txt   text;
  v_html        text;
BEGIN
  SELECT value INTO v_key FROM wsr_config WHERE key = 'resend_api_key';
  IF v_key IS NULL OR v_key = 'PEGA_TU_API_KEY_DE_RESEND_AQUI' THEN RETURN NEW; END IF;

  v_coach_email := public.wsr_coach_email_for_runner(NEW.runner_id);
  IF v_coach_email IS NULL THEN RETURN NEW; END IF;

  SELECT nombre_apellido INTO v_nombre FROM public.runners WHERE id = NEW.runner_id;
  v_nombre    := COALESCE(v_nombre, 'Una alumna');
  v_fecha_txt := to_char(NEW.week_start, 'DD/MM/YYYY');
  v_dolor_txt := NEW.pain::text || '/10' || COALESCE(' — ' || NULLIF(TRIM(NEW.pain_location), ''), '');

  v_html :=
    '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/></head>' ||
    '<body style="margin:0;padding:0;background:#FFF0F8;font-family:Helvetica Neue,Arial,sans-serif;">' ||
    '<div style="max-width:560px;margin:0 auto;padding:40px 16px 32px;">' ||
    '<p style="text-align:center;margin:0 0 28px;font-size:9px;letter-spacing:.35em;text-transform:uppercase;color:#D9488C;font-weight:500;">Woman Social Run</p>' ||
    '<div style="background:#fff;border:1px solid #FFD1F1;border-radius:4px;overflow:hidden;">' ||
